cat > 'systemd/webterm.service.template' <<'__WEBTERM_EOF__'
[Unit]
Description=Web terminal (xterm.js + node-pty)
Requires=webterm.socket
After=webterm.socket

[Service]
Type=simple
WorkingDirectory=__REPO_DIR__
ExecStart=__NODE__ server.js
Restart=on-failure
__WEBTERM_EOF__

cat > 'scripts/install-systemd.sh' <<'__WEBTERM_EOF__'
#!/usr/bin/env bash
set -euo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
NODE_BIN="$(command -v node)"
UNIT_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user"

mkdir -p "$UNIT_DIR"
sed -e "s|__REPO_DIR__|$REPO_DIR|g" -e "s|__NODE__|$NODE_BIN|g" \
  "$REPO_DIR/systemd/webterm.service.template" > "$UNIT_DIR/webterm.service"
cp "$REPO_DIR/systemd/webterm.socket" "$UNIT_DIR/webterm.socket"

systemctl --user daemon-reload
systemctl --user enable --now webterm.socket

echo "Installed. Open http://localhost:3000 (server starts on first visit, exits when idle)."
__WEBTERM_EOF__

cat > 'scripts/uninstall-systemd.sh' <<'__WEBTERM_EOF__'
#!/usr/bin/env bash
set -euo pipefail

UNIT_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user"

systemctl --user disable --now webterm.socket 2>/dev/null || true
systemctl --user stop webterm.service 2>/dev/null || true
rm -f "$UNIT_DIR/webterm.socket" "$UNIT_DIR/webterm.service"
systemctl --user daemon-reload

echo "Uninstalled."
__WEBTERM_EOF__

cat > 'test/smoke.js' <<'__WEBTERM_EOF__'
const { spawn } = require('child_process');
const WebSocket = require('ws');

const PORT = 3999;
const server = spawn('node', ['server.js'], {
  env: { ...process.env, PORT: String(PORT), IDLE_MS: '4000' },
  stdio: 'inherit',
});

const fail = (msg) => {
  console.error('FAIL:', msg);
  server.kill();
  process.exit(1);
};

const connect = (origin) =>
  new WebSocket(`ws://127.0.0.1:${PORT}/term`, { headers: { Origin: origin } });

function testBadOrigin(next) {
  const ws = connect('http://evil.example');
  let gotData = false;
  ws.on('message', () => (gotData = true));
  ws.on('error', () => {});
  const t = setTimeout(() => fail('bad origin was not closed'), 3000);
  ws.on('close', () => {
    clearTimeout(t);
    if (gotData) fail('bad origin received data');
    console.log('ok: bad origin rejected');
    next();
  });
}

function testRoundTrip(next) {
  const ws = connect(`http://localhost:${PORT}`);
  let out = '';
  ws.on('open', () =>
    // arithmetic so the typed echo differs from the command's real output
    ws.send(JSON.stringify({ type: 'input', data: 'echo web$((40+2))term\n' }))
  );
  ws.on('message', (d) => {
    out += d;
    if (out.includes('web42term')) ws.close();
  });
  const t = setTimeout(() => fail('no shell output'), 5000);
  ws.on('close', () => {
    clearTimeout(t);
    if (!out.includes('web42term')) fail('no shell output');
    console.log('ok: shell round-trip');
    next();
  });
}

function testIdleExit() {
  const t = setTimeout(() => fail('server did not exit after idle'), 10000);
  server.on('exit', (code) => {
    clearTimeout(t);
    console.log('ok: server exited when idle, code', code);
    process.exit(code === 0 ? 0 : 1);
  });
}

setTimeout(() => testBadOrigin(() => testRoundTrip(testIdleExit)), 1000);
__WEBTERM_EOF__

chmod +x scripts/*.sh

# --- install dependencies ----------------------------------------------------
echo "Installing npm dependencies (builds node-pty)..."
npm ci --no-audit --no-fund

if [ "$SERVICE" = 0 ]; then
  echo "Done. Start it manually with: cd '$TARGET' && npm start"
  exit 0
fi

# --- systemd user socket -----------------------------------------------------
command -v systemctl >/dev/null || die "systemctl not found; rerun with --no-service"
systemctl --user show-environment >/dev/null 2>&1 \
  || die "no systemd user session (log in graphically or via ssh, not su/sudo)"

bash scripts/install-systemd.sh

DROPIN="${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user/webterm.service.d"
if [ "$TMUX_MODE" = 1 ]; then
  mkdir -p "$DROPIN"
  printf '[Service]\nEnvironment=WEBTERM_TMUX=1\n' > "$DROPIN/tmux.conf"
else
  rm -f "$DROPIN/tmux.conf"
fi
systemctl --user daemon-reload

# Poke the socket once to prove activation works (server exits again when idle)
if command -v curl >/dev/null; then
  if curl -fsS --noproxy '*' -o /dev/null --max-time 10 http://127.0.0.1:3000/; then
    echo "Check: http://localhost:3000 answered, socket activation works."
  else
    echo "warning: http://localhost:3000 did not answer; see: journalctl --user -u webterm.service" >&2
  fi
fi
systemctl --user --no-pager status webterm.socket | head -n 3 || true
